"use client";

/**
 * Logo reveal: a set of pictures collapses into the product mark, and the
 * name sets beside it. Three ways in: an orbit, a fast flicker or a stack.
 *
 * Written by Better Design. The mark is the brand's initials on a primary
 * tile unless a mark image is given; missing pictures become gradient tiles.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { type ReactNode, useEffect, useState } from "react";
import { AbsoluteFill, continueRender, delayRender, Img, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, mix, pickFont, progress, shiftHue, springs, type VideoTheme, useVideoTheme, withAlpha, srcOf } from "@/lib/bd-video";

const { fontFamily: INTER, waitUntilDone } = loadFont("normal", { weights: ["600", "700"], subsets: ["latin"] });

const MARK = 208;
const CARD_W = 300;
const CARD_H = 380;
const NAME_SIZE = 128;
/** Frame gaps between flicker swaps: fast in the middle, slowing onto the mark. */
const FLICKER_GAPS = [7, 6, 5, 4, 3, 3, 2, 2, 2, 2, 2, 3, 3, 4, 5];
const FLICKER_START = 6;
const STACK_FLICKS = 4;

/** A shadow ink that stays dark in both modes, so a dark theme never glows. */
const shade = (alpha: number): string => `oklch(0.14 0.01 60 / ${alpha})`;

const initialsOf = (name: string): string =>
  name.split(/\s+/).filter(Boolean).slice(0, 2).map((word) => word.charAt(0)).join("").toUpperCase() || "B";

/** The name's set width, read from the loaded face, so the lockup stays centred while it opens. */
function nameWidth(name: string, family: string): number {
  const estimate = name.length * NAME_SIZE * 0.6;
  if (typeof document === "undefined") return estimate;
  const context = document.createElement("canvas").getContext("2d");
  if (!context) return estimate;
  context.font = `700 ${NAME_SIZE}px ${family}`;
  return context.measureText(name).width - name.length * NAME_SIZE * 0.045 + 8;
}

export interface LogoRevealProps {
  /** The brand name that sets beside the mark. */
  name?: string;
  /** An image path for the mark. Unset, the mark is the name's initials on a primary tile. */
  mark?: string;
  /** Image paths for the pictures that collapse into the mark. Unset, gradient tiles stand in. */
  pictures?: string[];
  /** orbit: cards revolve, then fold in. flicker: pictures flip fast and land on the mark. stack: a deck is flicked through. */
  variant?: "orbit" | "flicker" | "stack";
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

function Picture({ src, index, theme, w = CARD_W, h = CARD_H }: { src?: string; index: number; theme: VideoTheme; w?: number; h?: number }) {
  const hue = shiftHue(theme.primary, ((index * 41) % 140) - 70);
  return (
    <div
      style={{
        width: w,
        height: h,
        borderRadius: theme.radius + 10,
        overflow: "hidden",
        position: "relative",
        background: `linear-gradient(150deg, ${hue}, ${withAlpha(shiftHue(hue, 40), 0.6)}), ${theme.card}`,
        boxShadow: `0 30px 60px -24px ${shade(0.4)}, 0 0 0 1px ${withAlpha(theme.foreground, 0.06)}`,
      }}
    >
      {src ? (
        <Img src={srcOf(src)} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
      ) : (
        <>
          <div style={{ position: "absolute", width: w * 0.62, height: w * 0.62, borderRadius: "50%", right: -w * 0.12, top: h * 0.12, background: withAlpha(theme.primaryForeground, 0.18) }} />
          <div style={{ position: "absolute", left: 26, right: 26, bottom: 30, display: "flex", flexDirection: "column", gap: 12 }}>
            <div style={{ height: 14, width: "70%", borderRadius: 7, background: withAlpha(theme.primaryForeground, 0.85) }} />
            <div style={{ height: 14, width: "45%", borderRadius: 7, background: withAlpha(theme.primaryForeground, 0.45) }} />
          </div>
        </>
      )}
    </div>
  );
}

function Mark({ name, mark, theme, w, h }: { name: string; mark?: string; theme: VideoTheme; w: number; h: number }) {
  return (
    <div
      style={{
        width: w,
        height: h,
        flexShrink: 0,
        borderRadius: Math.min(w, h) * 0.24,
        overflow: "hidden",
        background: `linear-gradient(150deg, ${mix(theme.primary, theme.primaryForeground, 0.12)}, ${theme.primary})`,
        boxShadow: `0 24px 50px -20px ${withAlpha(theme.primary, 0.6)}`,
        color: theme.primaryForeground,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontSize: Math.min(w, h) * 0.42,
        fontWeight: 700,
        letterSpacing: "-0.04em",
      }}
    >
      {mark ? <Img src={srcOf(mark)} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : initialsOf(name)}
    </div>
  );
}

/** Pictures collapse into the product mark, then the name sets beside it. */
export function LogoReveal({
  name = "Your product",
  mark,
  pictures = [],
  variant = "orbit",
  theme: themeOverride,
  font,
}: LogoRevealProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);
  // Measure the name only once its face has loaded, or the first frames of a
  // render tab would centre the lockup on the fallback font's metrics.
  const [handle] = useState(() => delayRender("Measure the brand name"));
  const [measured, setMeasured] = useState<number | undefined>(undefined);
  useEffect(() => {
    Promise.all([waitUntilDone(), document.fonts.ready]).then(() => {
      setMeasured(nameWidth(name, family));
      continueRender(handle);
    });
  }, [handle, name, family]);
  const count = Math.max(pictures.length, variant === "stack" ? STACK_FLICKS + 2 : 8);
  const pic = (i: number) => (pictures.length ? pictures[i % pictures.length] : undefined);

  let cards: ReactNode = null;
  let markAt = 70;
  let markW = MARK;
  let markH = MARK;
  let markScale = 1;

  if (variant === "orbit") {
    const spin = easings.out(progress(frame, 0, 80)) * Math.PI * 2.2;
    const shrink = easings.in(progress(frame, 48, 24));
    const fade = 1 - progress(frame, 66, 8);
    const enter = easings.out(progress(frame, 0, 14));
    cards = Array.from({ length: count }, (_, i) => {
      const angle = (i / count) * Math.PI * 2 + spin;
      const depth = (Math.sin(angle) + 1) / 2;
      const x = Math.cos(angle) * 600 * (1 - shrink);
      const y = Math.sin(angle) * 150 * (1 - shrink);
      const s = (0.62 + 0.38 * depth) * (1 - 0.6 * shrink) * (0.8 + 0.2 * enter);
      return (
        <div key={i} style={{ position: "absolute", left: x - CARD_W / 2, top: y - CARD_H / 2, zIndex: Math.round(depth * 100), opacity: enter * fade * (0.55 + 0.45 * depth), transform: `scale(${s})` }}>
          <Picture src={pic(i)} index={i} theme={theme} />
        </div>
      );
    });
  } else if (variant === "flicker") {
    let at = FLICKER_START;
    let shown = 0;
    let since = frame;
    FLICKER_GAPS.forEach((gap, k) => {
      if (frame >= at) {
        shown = k;
        since = frame - at;
      }
      at += gap;
    });
    // `at` is now the frame the flicker lands on the mark.
    if (frame >= at) since = frame - at;
    const landed = frame >= at;
    const flip = 70 * (1 - easings.out(progress(since, 0, 3)));
    const enter = easings.out(progress(frame, 0, 10));
    const morph = easings.inOut(progress(frame, at + 6, 16));
    markW = CARD_W + (MARK - CARD_W) * morph;
    markH = CARD_H + (MARK - CARD_H) * morph;
    markAt = at;
    if (!landed) {
      cards = (
        <div style={{ position: "absolute", left: -CARD_W / 2, top: -CARD_H / 2, opacity: enter, transform: `perspective(1400px) rotateY(${flip}deg) scale(${0.9 + 0.1 * enter})` }}>
          <Picture src={pic(shown)} index={shown} theme={theme} />
        </div>
      );
    } else {
      markScale = 1 + 0.04 * (1 - easings.out(progress(since, 0, 6)));
    }
  } else {
    const flickAt = (j: number) => 12 + j * 7;
    const collapse = easings.inOut(progress(frame, flickAt(STACK_FLICKS) + 2, 14));
    markAt = flickAt(STACK_FLICKS) + 12;
    const enter = easings.out(progress(frame, 0, 14));
    const advanced = Array.from({ length: STACK_FLICKS }, (_, j) => easings.out(progress(frame, flickAt(j), 8))).reduce((a, b) => a + b, 0);
    cards = Array.from({ length: count }, (_, j) => {
      const flicked = j < STACK_FLICKS ? easings.out(progress(frame, flickAt(j), 12)) : 0;
      const depth = Math.max(0, j - advanced) * (1 - collapse);
      const shrinkTo = MARK / CARD_W;
      const s = (1 - depth * 0.05) * (1 - (1 - shrinkTo) * collapse);
      const side = j % 2 === 0 ? 1 : -1;
      const tilt = side * (2 + depth * 1.2) * (1 - collapse) + side * flicked * 24;
      const opacity = enter * (1 - progress(frame, flickAt(j) + 6, 6) * (j < STACK_FLICKS ? 1 : 0)) * (1 - progress(frame, markAt, 5));
      return (
        <div
          key={j}
          style={{
            position: "absolute",
            left: -CARD_W / 2,
            top: -CARD_H / 2,
            zIndex: count - j,
            opacity,
            transform: `translate(${side * flicked * 1300}px, ${depth * 16 - flicked * 140 + (1 - enter) * 60}px) rotate(${tilt}deg) scale(${s})`,
          }}
        >
          <Picture src={pic(j)} index={j} theme={theme} />
        </div>
      );
    });
  }

  if (variant !== "flicker") {
    markScale = spring({ frame: frame - markAt, fps, config: springs.bouncy, from: 0.7, to: 1 });
  }
  const markOpacity = variant === "flicker" ? (frame >= markAt ? 1 : 0) : progress(frame, markAt, 5);
  const revealAt = variant === "flicker" ? markAt + 22 : markAt + 12;
  const reveal = easings.out(progress(frame, revealAt, 22));
  const width = measured ?? nameWidth(name, family);

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden" }}>
      <AbsoluteFill style={{ background: `radial-gradient(ellipse 900px 600px at 50% 50%, ${withAlpha(theme.primary, 0.08)}, ${withAlpha(theme.primary, 0)} 70%)` }} />
      <div style={{ position: "absolute", left: "50%", top: "50%" }}>{cards}</div>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", opacity: markOpacity }}>
        <div style={{ display: "flex", alignItems: "center", gap: 48 * reveal }}>
          <div style={{ transform: `scale(${markScale})` }}>
            <Mark name={name} mark={mark} theme={theme} w={markW} h={markH} />
          </div>
          <div style={{ width: width * reveal, overflow: "hidden", whiteSpace: "nowrap" }}>
            <span
              style={{
                display: "inline-block",
                fontSize: NAME_SIZE,
                fontWeight: 700,
                letterSpacing: "-0.045em",
                lineHeight: 1.1,
                color: theme.foreground,
                opacity: reveal,
                transform: `translateX(${(1 - reveal) * -60}px)`,
              }}
            >
              {name}
            </span>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
}
